from pathlib import Path
import logging

logger = logging.getLogger(__name__)


class BaseQueryLoader:
    """Base para carregadores de query SQL."""
    BASE_DIR: Path  # Deve ser definido pela subclasse

    @classmethod
    def load(cls, name: str) -> str:
        logger.debug("Carregando query | nome=%s", name)
        path = cls.BASE_DIR / f"{name}.sql"
        if not path.is_file():
            raise FileNotFoundError(f"Query {name} não encontrada em {path}")
        return path.read_text(encoding="utf-8")

import logging
from concurrent.futures import ThreadPoolExecutor, as_completed
from twilio.rest import Client

_MAX_WORKERS = 4

logger = logging.getLogger(__name__)


class WhatsAppClient:
    def __init__(self, sid: str, token: str, from_number: str):
        self.client = Client(sid, token)
        self.from_number = f"whatsapp:{from_number}" if from_number else ""

    def enviar_texto(self, numero: str, mensagem: str) -> bool:
        try:
            msg = self.client.messages.create(
                body=mensagem,
                from_=self.from_number,
                to=f"whatsapp:{numero}",
            )
            logger.info("WhatsApp enviado | numero=%s sid=%s", numero, msg.sid)
            return msg.error_code is None
        except Exception as e:
            logger.error("Erro ao enviar WhatsApp | numero=%s erro=%s", numero, e)
            return False

    def enviar_para_lista(self, numeros: list[str], mensagem: str) -> dict[str, bool]:
        resultados: dict[str, bool] = {}
        with ThreadPoolExecutor(max_workers=_MAX_WORKERS) as executor:
            futuros = {executor.submit(self.enviar_texto, num, mensagem): num for num in numeros}
            for fut in as_completed(futuros):
                numero = futuros[fut]
                try:
                    resultados[numero] = fut.result()
                except Exception as e:
                    logger.error("Erro inesperado no WhatsApp paralelo | numero=%s erro=%s", numero, e)
                    resultados[numero] = False
        return resultados

from apscheduler.schedulers.background import BackgroundScheduler
from apscheduler.jobstores.base import JobLookupError
import logging

logger = logging.getLogger(__name__)

_scheduler: BackgroundScheduler | None = None


def init_scheduler_manager(scheduler: BackgroundScheduler):
    global _scheduler
    _scheduler = scheduler


def get_scheduler() -> BackgroundScheduler:
    if _scheduler is None:
        raise RuntimeError("Scheduler not initialized")
    return _scheduler


_DIA_MAPA = {
    "sun": "sun", "mon": "mon", "tue": "tue", "wed": "wed",
    "thu": "thu", "fri": "fri", "sat": "sat",
    "dom": "sun", "seg": "mon", "ter": "tue", "qua": "wed",
    "qui": "thu", "sex": "fri", "sab": "sat",
}


def dia_para_cron(dia: str) -> str:
    return _DIA_MAPA.get(dia.lower()[:3], "fri")


def _reschedule_or_add(job_id: str, trigger: str, func, **trigger_args):
    sched = get_scheduler()
    existing = sched.get_job(job_id)
    if existing:
        sched.reschedule_job(job_id, trigger=trigger, **trigger_args)
    elif func is not None:
        sched.add_job(
            func, trigger=trigger,
            id=job_id, replace_existing=True,
            misfire_grace_time=3600,
            **trigger_args
        )
    else:
        logger.warning("Job %s nao encontrado e sem func para recriar", job_id)
        return

    job = sched.get_job(job_id)
    if job:
        logger.info("Job %s | proxima_execucao=%s", job_id, job.next_run_time)


