"""Serviço de enriquecimento de Endereco via API externa (ViaCEP / BrasilAPI).

Uso futuro: ao salvar o CEP, chamar este serviço para preencher
automaticamente código IBGE, DDD e coordenadas no Value Object.

Independe do ConfigService — recebe e retorna um Endereco.
"""

import logging
from typing import Optional
from app.domain.value_objects.endereco import Endereco

logger = logging.getLogger(__name__)


def enriquecer_por_cep(endereco: Endereco) -> Endereco:
    """Busca dados complementares (IBGE, DDD, coordenadas) a partir do CEP.

    Usa a BrasilAPI (https://brasilapi.com.br/api/cep/v1/{cep}) como fonte
    primária, com fallback para ViaCEP.

    Retorna o mesmo Endereco com os campos de Nível 2 preenchidos.
    Se a API falhar ou o CEP não for encontrado, retorna o objeto original.
    """
    cep = endereco.cep
    if not cep or len(cep) != 8 or not cep.isdigit():
        return endereco

    dados = _buscar_brasilapi(cep) or _buscar_viacep(cep)
    if not dados:
        return endereco

    return endereco.model_copy(update={
        "codigo_ibge": dados.get("ibge"),
        "ddd": dados.get("ddd"),
        "latitude": dados.get("latitude"),
        "longitude": dados.get("longitude"),
    })


def _buscar_brasilapi(cep: str) -> Optional[dict]:
    """Tenta enriquecer via BrasilAPI (recomendada)."""
    try:
        import httpx
        resp = httpx.get(f"https://brasilapi.com.br/api/cep/v1/{cep}", timeout=5)
        if resp.status_code != 200:
            return None
        data = resp.json()
        return {
            "ibge": data.get("ibge"),
            "ddd": data.get("ddd"),
            "latitude": _parse_float(data.get("latitude")),
            "longitude": _parse_float(data.get("longitude")),
        }
    except Exception as e:
        logger.debug("BrasilAPI falhou para CEP %s: %s", cep, e)
        return None


def _buscar_viacep(cep: str) -> Optional[dict]:
    """Fallback para ViaCEP."""
    try:
        import httpx
        cep_fmt = f"{cep[:5]}-{cep[5:]}"
        resp = httpx.get(f"https://viacep.com.br/ws/{cep_fmt}/json/", timeout=5)
        if resp.status_code != 200:
            return None
        data = resp.json()
        if data.get("erro"):
            return None
        return {
            "ibge": data.get("ibge"),
            "ddd": data.get("ddd"),
            "latitude": None,  # ViaCEP não retorna coordenadas
            "longitude": None,
        }
    except Exception as e:
        logger.debug("ViaCEP falhou para CEP %s: %s", cep, e)
        return None


def _parse_float(valor) -> Optional[float]:
    if valor is None:
        return None
    try:
        return float(valor)
    except (ValueError, TypeError):
        return None

import re
from typing import Optional


class Codigo:
    def __init__(self, valor: str) -> None:
        """Inicializa o código validando o valor e detectando seu tipo (EAN, PLU)."""
        if not isinstance(valor, str):
            raise TypeError("Codigo deve ser uma string")
        normalizado = self.normalizar(valor)
        if not self.validar(normalizado):
            raise ValueError(f"Codigo invalido: {valor!r}")
        self._valor = normalizado
        self._tipo = self.detectar_tipo(normalizado)

    @property
    def valor(self) -> str:
        return self._valor

    @property
    def tipo(self) -> Optional[str]:
        return self._tipo

    @staticmethod
    def normalizar(codigo: str) -> str:
        """Remove espaços e traços, faz zero-padding e retorna o código limpo."""
        codigo = codigo.strip()
        codigo = re.sub(r"[\s-]", "", codigo)
        if codigo.isdigit() and 1 <= len(codigo) <= 6:
            codigo = codigo.zfill(6)
        return codigo

    @classmethod
    def validar(cls, codigo: str) -> bool:
        """Valida se o código é de algum tipo suportado (EAN ou PLU)."""
        return cls.detectar_tipo(codigo) is not None

    @classmethod
    def detectar_tipo(cls, codigo: str) -> Optional[str]:
        """Identifica o tipo do código: EAN13, EAN12, EAN8 ou PLU6."""
        if cls.is_ean13(codigo):
            return "EAN13"
        if cls.is_ean12(codigo):
            return "EAN12"
        if cls.is_ean8(codigo):
            return "EAN8"
        if cls.is_plu6(codigo):
            return "PLU6"
        return None

    @classmethod
    def is_ean13(cls, codigo: str) -> bool:
        """Verifica se o código é um EAN-13 válido."""
        return cls._validar_ean(codigo, 13)

    @classmethod
    def is_ean12(cls, codigo: str) -> bool:
        """Verifica se o código é um EAN-12 válido."""
        return cls._validar_ean(codigo, 12)

    @classmethod
    def is_ean8(cls, codigo: str) -> bool:
        """Verifica se o código é um EAN-8 válido."""
        return cls._validar_ean(codigo, 8)

    @staticmethod
    def is_plu6(codigo: str) -> bool:
        """Verifica se o código é um PLU de 6 dígitos válido."""
        return codigo.isdigit() and 1 <= len(codigo) <= 6

    @staticmethod
    def _validar_ean(codigo: str, tamanho: int) -> bool:
        """Valida um código EAN usando o algoritmo de dígito verificador."""
        if len(codigo) != tamanho or not codigo.isdigit():
            return False
        corpo = codigo[:-1]
        digito = int(codigo[-1])
        soma = 0
        peso = 3
        for ch in reversed(corpo):
            soma += int(ch) * peso
            peso = 1 if peso == 3 else 3
        calculado = (10 - (soma % 10)) % 10
        return calculado == digito

    def __repr__(self):
        return f"Codigo({self._valor})"

    def __eq__(self, other):
        if isinstance(other, Codigo):
            return self.valor == other.valor
        return False

"""Value Object Endereco.

Encapsula os dados de endereço do estabelecimento com validação,
formatação humano/IA e preparação para enriquecimento futuro
(IBGE, coordenadas, dados demográficos).
"""

import re
from typing import Optional
from pydantic import BaseModel, field_validator


_UFS_VALIDAS: set[str] = {
    "AC", "AL", "AP", "AM", "BA", "CE", "DF", "ES", "GO",
    "MA", "MT", "MS", "MG", "PA", "PB", "PR", "PE", "PI",
    "RJ", "RN", "RS", "RO", "RR", "SC", "SP", "SE", "TO",
}

_RE_CEP = re.compile(r"^\d{5}-?\d{3}$")


def validar_cep(valor: str) -> str:
    """Valida e normaliza CEP. Retorna 8 dígitos sem máscara."""
    if not _RE_CEP.match(valor.strip()):
        raise ValueError(
            f"CEP inválido: {valor!r}. Use o formato 01001000 ou 01001-000."
        )
    return valor.strip().replace("-", "")


def validar_uf(valor: str) -> str:
    """Valida e normaliza UF. Retorna sigla em maiúsculo."""
    uf = valor.strip().upper()
    if uf not in _UFS_VALIDAS:
        raise ValueError(
            f"UF inválida: {valor!r}. Use uma sigla de 2 letras (SP, RJ, MG, ...)."
        )
    return uf


def formatar_cep(cep: str) -> str:
    """Formata CEP de 8 dígitos para 01001-000."""
    if len(cep) == 8 and cep.isdigit():
        return f"{cep[:5]}-{cep[5:]}"
    return cep


class Endereco(BaseModel):
    """Value Object para dados de endereço do estabelecimento.

    Nível 1 — campos preenchidos pelo ConfigService (configurados na UI):
        rua, numero, complemento, bairro, cidade, estado, cep

    Nível 2 — campos enriquecidos por API externa (ViaCEP, BrasilAPI),
        opcionais, preparados para consumo futuro pela IA.

    Nível 3 (futuro, comentado) — dados demográficos censitários:
        idh, renda_media, densidade_populacional, etc.
    """

    # ── Nível 1: ConfigService ──────────────────────────────────────────
    rua: str = ""
    numero: str = ""
    complemento: str = ""
    bairro: str = ""
    cidade: str = ""
    estado: str = ""
    cep: str = ""

    # ── Nível 2: Enriquecido por API externa ────────────────────────────
    codigo_ibge: Optional[str] = None
    ddd: Optional[str] = None
    latitude: Optional[float] = None
    longitude: Optional[float] = None

    # ── Nível 3: Dados demográficos (sob demanda, futuros) ──────────────
    # idh: Optional[float] = None
    # renda_media: Optional[float] = None
    # densidade_populacional: Optional[float] = None
    # urbanizacao: Optional[float] = None

    # ── Validators ──────────────────────────────────────────────────────

    @field_validator("cep")
    @classmethod
    def _validar_cep(cls, v: str) -> str:
        if not v:
            return v
        return validar_cep(v)

    @field_validator("estado")
    @classmethod
    def _validar_uf(cls, v: str) -> str:
        if not v:
            return v
        return validar_uf(v)

    # ── Propriedades de formatação ──────────────────────────────────────

    @property
    def cep_formatado(self) -> str:
        """CEP no formato 01001-000."""
        return formatar_cep(self.cep) if self.cep else ""

    @property
    def formatado(self) -> str:
        """String legível para humanos (exibição na UI, relatórios)."""
        parts = []
        linha1 = self.rua
        if self.numero:
            linha1 += f", {self.numero}"
        if self.complemento:
            linha1 += f" — {self.complemento}"
        parts.append(linha1)

        linha2 = self.bairro
        if self.cidade:
            linha2 += f", {self.cidade}"
        if self.estado:
            linha2 += f" - {self.estado}"
        parts.append(linha2)

        if self.cep:
            parts.append(f"CEP {self.cep_formatado}")

        return " | ".join(p for p in parts if p)

    @property
    def completo(self) -> bool:
        """Retorna True se todos os campos obrigatórios estão preenchidos."""
        return all([self.rua, self.numero, self.bairro, self.cidade, self.estado, self.cep])

    # ── Saída otimizada pra IA ──────────────────────────────────────────

    def para_prompt_ia(self) -> str:
        """Bloco estruturado para alimentar schemas de prompt de IA.

        Usa labels claros e sem ambiguidade, ideal para extração por LLM
        ou montagem de contexto enriquecido.
        """
        return (
            f"LOGRADOURO: {self.rua}\n"
            f"NUMERO: {self.numero}\n"
            f"COMPLEMENTO: {self.complemento or '(vazio)'}\n"
            f"BAIRRO: {self.bairro}\n"
            f"CIDADE: {self.cidade}\n"
            f"ESTADO: {self.estado}\n"
            f"CEP: {self.cep_formatado or '(vazio)'}\n"
            f"IBGE: {self.codigo_ibge or '(não informado)'}\n"
            f"DDD: {self.ddd or '(não informado)'}\n"
            f"LAT: {self.latitude if self.latitude is not None else '(não informado)'}\n"
            f"LNG: {self.longitude if self.longitude is not None else '(não informado)'}"
        )

    def para_json_ia(self) -> dict:
        """Dicionário limpo para consumo da IA via tool call."""
